async function (vars) {
    var roiGrid = new GridWidget(vars.element, vars.data);
    roiGrid.editable = false;
    roiGrid.sortable = false;
    roiGrid.filterable = false;
    roiGrid.pageable = false;
    roiGrid.groupable = false;
    roiGrid.toolbar = "<button name='addROI'><span class='k-icon k-i-plus'></span>[resource_displayname[New]]</button><button name='getPack'><span class='k-icon k-i-download'></span>[resource_displayname[downloadContract]]</button>";
    roiGrid.columns = [
        { field: "email", type: "string", title: "[resource_shortdisplayname[userEmail]]", width: 100, template: "#=JSON.parse(DataJson).fields[0].email#" },
        { field: "companyName", type: "string", title: "[resource_shortdisplayname[company]]", width: 100, template: "#=JSON.parse(DataJson).fields[1].company#" },
        { field: "CreatedOn", type: "date", title: "[resource_shortdisplayname[requestDate]]", width: 100, format: "{0:" + type.dateFormat + "}" },
        { field: "CreatedBy", title: "[resource_shortdisplayname[CreatedBy]]", width: 100 },
        { field: "State", type: "string", title: "[resource_shortdisplayname[requestState]]", width: 100, template: "#=RegistrationOfInterest.states[State]#" },
        { field: "requestType", type: "string", title: "[resource_shortdisplayname[fundingType]]", width: 100, template: "#=JSON.parse(DataJson).fields[1].requestType#" }
    ];
    return roiGrid;
}
